"""
ai/schemas.py - Common Schemas for AI Interaction.

Re-exports and provides Pydantic schemas used across AI reasoning,
intent extraction, and agent dialogue synthesis.
"""

from __future__ import annotations

from typing import Optional
from pydantic import BaseModel, Field

from intents.schema import StructuredIntent, IntentType, LanguageCode, IntentEntities


class AgentDialogueResponse(BaseModel):
    """Structured dialogue response generated by an agent."""
    speaker: str = Field(..., description="Agent producing the speech ('miss_minutes' or 'jarvis').")
    spoken_text: str = Field(..., description="Text intended for speech synthesis.")
    display_text: Optional[str] = Field(None, description="Optional text for UI display.")
    expression: Optional[str] = Field(None, description="Suggested Miss Minutes expression (e.g. 'HAPPY', 'THINKING').")
    should_delegate: bool = Field(False, description="Whether to delegate next step to partner agent.")
    delegate_to: Optional[str] = Field(None, description="Target agent name if delegating.")
    delegation_payload: Optional[str] = Field(None, description="Task details for delegated agent.")


__all__ = [
    "StructuredIntent",
    "IntentType",
    "LanguageCode",
    "IntentEntities",
    "AgentDialogueResponse",
]
